<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();$id=max(1,(int)($_GET['id']??0));$s=$db->prepare("SELECT d.*,cr.libelle categorie,c.type_client,c.nom,c.prenom,c.raison_sociale,c.numero_client FROM demandes_devis d JOIN categories_risque cr ON cr.id=d.categorie_id JOIN clients c ON c.id=d.client_id WHERE d.id=?");$s->execute([$id]);$d=$s->fetch()?:exit('Demande introuvable.');$s=$db->prepare("SELECT o.*,p.nom produit,p.code_produit,co.raison_sociale compagnie,(SELECT COUNT(*) FROM offres_garanties og WHERE og.offre_id=o.id AND og.incluse=1) nb_garanties,(SELECT GROUP_CONCAT(CONCAT(g.libelle,'|',COALESCE(og.plafond_propose,0),'|',og.franchise_proposee) SEPARATOR ';;') FROM offres_garanties og JOIN garanties g ON g.id=og.garantie_id WHERE og.offre_id=o.id AND og.incluse=1) details FROM offres_devis o JOIN produits_assurance p ON p.id=o.produit_id JOIN compagnies co ON co.id=p.compagnie_id WHERE o.demande_id=? ORDER BY o.score_global DESC,o.prime_totale");$s->execute([$id]);$offers=$s->fetchAll();$best=$offers[0]['id']??0;$client=$d['type_client']==='entreprise'?$d['raison_sociale']:trim($d['prenom'].' '.$d['nom']);$title='Comparateur';require __DIR__.'/../../includes/header.php';?>
<div class="page-heading"><div><h1 class="h3">Comparateur multi-compagnies</h1><p class="text-secondary mb-0"><?= e($d['numero_demande'].' · '.$client.' · '.$d['categorie']) ?></p></div><div><a class="btn btn-outline-secondary" href="index.php">Retour</a> <form class="d-inline" method="post" action="calculer.php"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $id ?>"><button class="btn btn-primary">Recalculer</button></form></div></div>
<div class="alert alert-info"><strong>Classement :</strong> 40 % prix + 40 % garanties + 20 % franchise. Paramètres de démonstration : taxes 14 % et frais 3 000 FCFA.</div>
<?php if(!$offers): ?><div class="alert alert-warning">Aucune offre calculée.</div><?php else: ?><div class="comparison-grid"><?php foreach($offers as $o): ?><article class="card offer-card <?= (int)$o['id']===(int)$best?'best-offer':'' ?>"><div class="card-body"><?php if((int)$o['id']===(int)$best): ?><span class="best-label">Meilleur score</span><?php endif; ?><div class="d-flex justify-content-between gap-3"><div><div class="text-secondary small"><?= e($o['compagnie']) ?></div><h2 class="h5 mt-1"><?= e($o['produit']) ?></h2><div class="small text-secondary"><?= e($o['code_produit']) ?></div></div><div class="score-circle"><?= number_format((float)$o['score_global'],0) ?><small>/100</small></div></div><div class="premium my-4"><?= number_format((float)$o['prime_totale'],0,',',' ') ?> <small>FCFA/an</small></div><div class="score-bars"><div><span>Prix</span><progress max="100" value="<?= e((string)$o['score_prix']) ?>"></progress><b><?= number_format((float)$o['score_prix'],0) ?></b></div><div><span>Garanties</span><progress max="100" value="<?= e((string)$o['score_garanties']) ?>"></progress><b><?= number_format((float)$o['score_garanties'],0) ?></b></div><div><span>Franchise</span><progress max="100" value="<?= e((string)$o['score_franchise']) ?>"></progress><b><?= number_format((float)$o['score_franchise'],0) ?></b></div></div><hr><h3 class="h6"><?= (int)$o['nb_garanties'] ?> garantie(s)</h3><ul class="guarantee-list"><?php foreach(array_filter(explode(';;',(string)$o['details'])) as $detail): $parts=explode('|',$detail);?><li><span><?= e($parts[0]??'') ?></span><small>Plafond <?= number_format((float)($parts[1]??0),0,',',' ') ?> · Franchise <?= number_format((float)($parts[2]??0),0,',',' ') ?></small></li><?php endforeach ?></ul><details class="mt-3"><summary>Détail du prix</summary><div class="small mt-2">Prime nette : <?= number_format((float)$o['prime_nette'],0,',',' ') ?> FCFA<br>Taxes : <?= number_format((float)$o['taxes'],0,',',' ') ?> FCFA<br>Frais : <?= number_format((float)$o['frais'],0,',',' ') ?> FCFA</div></details></div></article><?php endforeach ?></div><?php endif; ?>
